-- 0056_jlpt_restart_20260907.sql
-- Reset JLPT N1 study progress and restart curated daily words from 2026-09-07.
PRAGMA foreign_keys = ON;

UPDATE japanese_admin_word_learning_stats
SET learning_state='unlearned', correct_count=0, wrong_count=0,
    last_answered_at=NULL, last_correct_at=NULL, last_wrong_at=NULL,
    first_learned_at=NULL, last_studied_at=NULL, review_stage=0,
    next_review_on=NULL, long_review_stage=0,
    updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE EXISTS (
  SELECT 1 FROM japanese_jlpt_study_plans p
  JOIN japanese_jlpt_curriculum_words c ON c.plan_id=p.id
  WHERE p.plan_code='N1_2027_JUL'
    AND p.admin_id=japanese_admin_word_learning_stats.admin_id
    AND c.word_id=japanese_admin_word_learning_stats.word_id
);

DELETE FROM japanese_jlpt_question_attempts WHERE plan_id IN (SELECT id FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL');
DELETE FROM japanese_jlpt_wrong_notes WHERE plan_id IN (SELECT id FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL');
DELETE FROM japanese_jlpt_cumulative_tests WHERE plan_id IN (SELECT id FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL');
DELETE FROM japanese_jlpt_daily_sessions WHERE plan_id IN (SELECT id FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL');
DELETE FROM japanese_jlpt_daily_contents WHERE plan_id IN (SELECT id FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL');
DELETE FROM japanese_jlpt_curriculum_words WHERE plan_id IN (SELECT id FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL');

UPDATE japanese_jlpt_study_plans
SET study_start_date='2026-09-07', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE plan_code='N1_2027_JUL';

